import { FONTS, UI_WEIGHTS, familyParameter, fontStylesheetUrl, googleFamily } from './compile';

export const CATEGORIES = { s: 'Sans serif', f: 'Serif', d: 'Display', h: 'Handwriting', m: 'Monospace' };

export const SAMPLE_TEXT = 'Grumpy wizards make toxic brew for the evil queen and jack';

let catalogue = null;

// Generated by scripts/build-google-fonts.mjs; loaded on demand.
export async function loadFontCatalogue() {
    if (!catalogue) {
        catalogue = import('./google-fonts.json')
            .then(({ default: data }) => data.families.map(([family, category, weights]) => Object.freeze({ family, category: CATEGORIES[category], weights })))
            .catch((error) => {
                catalogue = null;

                throw error;
            });
    }

    return catalogue;
}

export async function fontWeights(font) {
    const family = googleFamily(font);

    if (FONTS.includes(font) || FONTS.includes(family)) return UI_WEIGHTS;

    let entries;

    try {
        entries = await loadFontCatalogue();
    } catch {
        return [400];
    }

    const entry = entries.find((item) => item.family === family);

    return entry ? entry.weights : [400];
}

export async function resolveFontUrl(font) {
    return font === 'Inter var' ? null : fontStylesheetUrl(font, await fontWeights(font));
}

// `text` subsets the font to the characters of its name and the sample.
export function previewFontUrl(entry) {
    const weight = entry.weights.includes(400) ? 400 : entry.weights[0];
    const characters = [...new Set(entry.family + SAMPLE_TEXT)].sort().join('');

    return `https://fonts.googleapis.com/css2?family=${familyParameter(entry.family)}:wght@${weight}&text=${encodeURIComponent(characters)}&display=swap`;
}
